from taf.sbts.oam.coam.admin.utils import raise_value_error
import six


class LTEDownlink(object):
    def __init__(self, dist_name, test_model, earfcn, phy_cell_id, p_max, connector_dn, downlink_ch_bw,
                 inband_prbi_index_dl, guardband_index_dl, guardband_dl_freq_offset, tdd_frame_conf,
                 tdd_spec_sub_conf, laa_pattern_id, load_level):

        self.dist_name = dist_name

        self.test_model = self.validate_param('testModel',
                                              test_model,
                                              (test_model in (
                                                  "E_TM1_1", "E_TM1_2", "E_TM1_3", "E_TM2", "E_TM2a", "E_TM3_1a", "E_TM3_1",
                                                  "E_TM3_2", "E_TM3_3", "MIMO_TM3_1", "E_TM1_1_EE_LOW", "E_TM1_1_EE_MID",
                                                  "E_TM1_1_EE_HIGH", "E_TM1_1_EE_HIGHER", "E_TM1_1_EE_HIGHEST", "ChirpUp",
                                                  "ChirpDown", "E_TM1_1_ETSI", "IDLE_ACTIVE"
                                              ))
                                              )

        self.earfcn = self.validate_param('earfcn',
                                          earfcn,
                                          (earfcn is None or (0 <= earfcn <= 262143)))

        self.phy_cell_id = self.validate_param('phyCellId',
                                               phy_cell_id,
                                               (phy_cell_id is None or (0 <= phy_cell_id <= 1007)))

        self.p_max = self.validate_param('pMax',
                                         p_max,
                                         (p_max is None or (0 <= p_max <= 60)))

        self.connector_dn = self.validate_param('connectorDN',
                                                connector_dn,
                                                (connector_dn is None or (isinstance(connector_dn, six.string_types))))

        self.downlink_ch_bw = self.validate_param('downlinkChBw',
                                                  downlink_ch_bw,
                                                  (downlink_ch_bw is None or downlink_ch_bw in (
                                                      "NotDefined", "0_2MHz", "1_4MHz",
                                                      "3MHz", "5MHz", "10MHz", "15MHz",
                                                      "20MHz", "05_05MHz", "05_10MHz",
                                                      "10_05MHz", "10_10MHz")))

        self.inband_prbi_index_dl = self.validate_param(
            'inbandPRBIndexDl',
            inband_prbi_index_dl,
            (inband_prbi_index_dl is None or (0 <= inband_prbi_index_dl <= 99)))

        self.guardband_index_dl = self.validate_param('guardbandIndexDl',
                                                      guardband_index_dl,
                                                      (guardband_index_dl is None or (0 <= guardband_index_dl <= 99)))

        self.guardband_dl_freq_offset = self.validate_param(
            'guardbandDlFreqOffset',
            guardband_dl_freq_offset,
            (guardband_dl_freq_offset is None or (-2147483648 <= guardband_dl_freq_offset <= 2147483647)))

        self.tdd_frame_conf = self.validate_param('tddFrameConf',
                                                  tdd_frame_conf,
                                                  (tdd_frame_conf is None or (1 <= tdd_frame_conf <= 3)))

        self.tdd_spec_sub_conf = self.validate_param('tddSpecSubfConf',
                                                     tdd_spec_sub_conf,
                                                     (tdd_spec_sub_conf is None or (3 <= tdd_spec_sub_conf <= 9)))

        self.laa_pattern_id = self.validate_param('laaPatternId',
                                                  laa_pattern_id,
                                                  (laa_pattern_id is None or laa_pattern_id in (
                                                      'DTX', 'PCTX_7_3', 'PCTX_10_2')))

        self.load_level = self.validate_param('loadLevel',
                                              load_level,
                                              (load_level is None or load_level in (
                                                  "load_0_low", "load_10", "load_30_medium", "load_50_busy_hour",
                                                  "load_70")))

    @classmethod
    def from_response_dict(cls, response_dict):

        params = response_dict['params']
        dist_name = response_dict['lncel_rDN']
        test_model = params['testModel']
        earfcn = params['earfcn'] if 'earfcn' in params else None
        phy_cell_id = params['phyCellId'] if 'phyCellId' in params else None
        p_max = params['pMax'] if 'pMax' in params else None
        connector_dn = params['connectorDN'] if 'connectorDN' in params else None
        downlink_ch_bw = params['downlinkChBw'] if 'downlinkChBw' in params else None
        inband_prbi_index_dl = params['inbandPRBIndexDl'] if 'inbandPRBIndexDl' in params else None
        guardband_index_dl = params['guardbandIndexDl'] if 'guardbandIndexDl' in params else None
        guardband_dl_freq_offset = params['guardbandDlFreqOffset'] if 'guardbandDlFreqOffset' in params else None
        tdd_frame_conf = params['tddFrameConf'] if 'tddFrameConf' in params else None
        tdd_spec_sub_conf = params['tddSpecSubfConf'] if 'tddSpecSubfConf' in params else None
        laa_pattern_id = params['laaPatternId'] if 'laaPatternId' in params else None
        load_level = params['loadLevel'] if 'loadLevel' in params else None

        return cls(
            dist_name=dist_name,
            test_model=test_model,
            earfcn=earfcn,
            phy_cell_id=phy_cell_id,
            p_max=p_max,
            connector_dn=connector_dn,
            downlink_ch_bw=downlink_ch_bw,
            inband_prbi_index_dl=inband_prbi_index_dl,
            guardband_index_dl=guardband_index_dl,
            guardband_dl_freq_offset=guardband_dl_freq_offset,
            tdd_frame_conf=tdd_frame_conf,
            tdd_spec_sub_conf=tdd_spec_sub_conf,
            laa_pattern_id=laa_pattern_id,
            load_level=load_level
        )

    def as_dict(self):
        attributes = {'lncel_rDN': self.dist_name,
                      'params': {'testModel': self.test_model,
                                 'earfcn': self.earfcn,
                                 'phyCellId': self.phy_cell_id,
                                 'pMax': self.p_max,
                                 'connectorDN': self.connector_dn,
                                 'downlinkChBw': self.downlink_ch_bw,
                                 'inbandPRBIndexDl': self.inband_prbi_index_dl,
                                 'guardbandIndexDl': self.guardband_index_dl,
                                 'guardbandDlFreqOffset': self.guardband_dl_freq_offset,
                                 'tddFrameConf': self.tdd_frame_conf,
                                 'tddSpecSubfConf': self.tdd_spec_sub_conf,
                                 'laaPatternId': self.laa_pattern_id,
                                 'loadLevel': self.load_level
                                 }
                      }

        attributes['params'] = {k: v for k, v in attributes['params'].items() if v is not None}

        return attributes

    @staticmethod
    def validate_param(param, value, valid):
        return value if valid else raise_value_error(
            param=param,
            value=str(value),
            subpage="tutorial-startLteDownlinkTest.html")
